const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '拉力 F' },
      { kind: 'text', payload: '瓶内气压与摩擦的合力' },
      { kind: 'text', payload: '木塞' }
    ];
  },
  render: function (input, metrics) {
    var vp = input.viewport || {};
    var w = vp.widthDu || 360;
    var h = vp.heightDu || 420;
    var cx = w * 0.30;
    var neckHalf = w * 0.13;
    var bodyHalf = w * 0.22;
    var rimY = h * 0.24;
    var corkTop = h * 0.26;
    var corkBottom = h * 0.42;
    var shoulderY = h * 0.62;
    var bodyBottom = h * 0.95;
    var corkHalf = neckHalf * 0.92;
    var m = metrics || [];
    var m1 = m[1] || {};

    var bottle = visualSdk.polyline([
      [cx - neckHalf, rimY],
      [cx - neckHalf, shoulderY],
      [cx - bodyHalf, shoulderY + h * 0.10],
      [cx - bodyHalf, bodyBottom],
      [cx + bodyHalf, bodyBottom],
      [cx + bodyHalf, shoulderY + h * 0.10],
      [cx + neckHalf, shoulderY],
      [cx + neckHalf, rimY]
    ]);
    var rim = visualSdk.polyline([[cx - neckHalf, rimY], [cx + neckHalf, rimY]]);
    var cork = visualSdk.polyline([
      [cx - corkHalf, corkTop],
      [cx + corkHalf, corkTop],
      [cx + corkHalf, corkBottom],
      [cx - corkHalf, corkBottom],
      [cx - corkHalf, corkTop]
    ]);
    var fArrow = visualSdk.arrow(cx, corkTop, cx, h * 0.07, {});
    var dArrow = visualSdk.arrow(cx, corkBottom, cx, h * 0.58, {});

    var longW = m1.width || (12 * 11);
    var longX = cx + neckHalf + 10;
    var maxRight = w - 8;
    if (longX + longW > maxRight) {
      longX = Math.max(cx + 6, maxRight - longW);
    }

    return {
      schemaVersion: 1,
      sceneId: 'cork-force',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'bottle', commands: bottle },
        { id: 'rim', commands: rim },
        { id: 'cork', commands: cork },
        { id: 'fArrow', commands: fArrow },
        { id: 'dArrow', commands: dArrow }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'bottle', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
        { type: 'path', pathId: 'rim', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
        { type: 'path', pathId: 'cork', stroke: '#8a5a2b', strokeWidth: 1.6, fill: '#e8d3a9' },
        { type: 'path', pathId: 'fArrow', stroke: '#c0392b', strokeWidth: 2, fill: 'none' },
        { type: 'path', pathId: 'dArrow', stroke: '#1f6fb2', strokeWidth: 2, fill: 'none' },
        { type: 'label', text: '木塞', x: cx, y: (corkTop + corkBottom) / 2, fontSize: 12, anchor: 'middle', fill: '#5b3a17' },
        { type: 'label', text: '拉力 F', x: cx + 12, y: h * 0.12, fontSize: 15, anchor: 'start', fill: '#c0392b' },
        { type: 'label', text: '瓶内气压与摩擦的合力', x: longX, y: corkBottom + h * 0.08, fontSize: 12, anchor: 'start', fill: '#1f6fb2' }
      ] }
    };
  }
};
